/**
 * Multi-account: the Agent usage dropdown with two Claude accounts and a
 * Codex one side by side, ported from the app's UsageMenu
 * (src/panels/UsageMenu.tsx) and UsageSpend (src/panels/UsageSpend.tsx).
 * Each account is a config folder of its own (~/.claude, ~/.claude-work,
 * ~/.codex), found by the server (server/lib/accounts.js); its card shows
 * the plan, the signed-in email and its own limits. Left / Used switches
 * every bar, like the app.
 */
