// A corner card like the other dropdown scenes (CORNER), taller so the three
// accounts' cards fit under the top bar (the panel ends at window y 614): it
// ends between two terminal rows of the lower tiles, at least 16px under it.
const CARD = { width: CORNER.width, height: 24 + cleanY(614 + 16, 2) };

// The app's formatters (src/panels/UsageSpend.tsx).
function fmtCost(c: number): string {
  if (c >= 1000) return `$${(c / 1000).toFixed(1)}K`;
  if (c >= 100) return `$${Math.round(c).toLocaleString("en-US")}`;
  return `$${c.toFixed(2)}`;
}
function fmtTokens(n: number): string {
  if (n >= 1e9) return `${(n / 1e9).toFixed(1)}B`;
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
  if (n >= 1e3) return `${(n / 1e3).toFixed(1)}K`;
  return `${Math.round(n)}`;
}

// The app's barColor: the colour follows how much is used, whatever the number shows.
function barColor(used: number): string {
  if (used >= 90) return "#e5484d";
  if (used >= 70) return "#d9a441";
  return "#5fb37f";
}

interface Day {
  day: string;
  tokens: number;
  cost: number;
}

/** Thirty days ending on the demo's today, from millions of tokens per day and a blended $/M rate. */
function days(millions: number[], rate: number): Day[] {
  const today = Date.UTC(2026, 10, 11);
  return millions.map((m, i) => ({
    day: new Date(today - (millions.length - 1 - i) * 86_400_000).toISOString().slice(0, 10),
    tokens: m * 1e6,
    cost: m * rate,
  }));
}

interface Limit {
  label: string;
  used: number;
  /** fmtReset, fmtResetShort and fmtResetAbs of its reset time. */
  reset: string;
  short: string;
  abs: string;
  /** The row the menu bar shows on Auto: the highest usage of every account. */
  auto?: boolean;
}

interface Account {
  agent: "claude" | "codex";
  name: string;
  color: string;
  plan: string;
  email: string;
  limits: Limit[];
  days: Day[];
}

