type UsageModeName = "left" | "used";

/** The app's Bar with its menu bar pin, showing the share left or used. */
function Bar({ limit, account, mode }: { limit: Limit; account: string; mode: UsageModeName }) {
  const shown = mode === "used" ? limit.used : 100 - limit.used;
  return (
    <div className="usage-bar-row">
      <div className="usage-bar-top">
        <span className="usage-bar-text" title={`${limit.label} ${shown}% ${mode} · resets in ${limit.reset} (${limit.abs})`}>
          <span className="usage-bar-label">{limit.label}</span>
          <span className="usage-bar-pct">{shown}%</span>
          <span className="usage-bar-reset">
            · {limit.reset} <span className="usage-bar-reset-abs">{limit.short}</span>
          </span>
        </span>
        <button
          type="button"
          className={`usage-pin ${limit.auto ? "is-auto" : ""}`}
          aria-pressed="false"
          aria-label={`Show ${account} ${limit.label} in the menu bar`}
          title={limit.auto ? "Shown in the menu bar automatically (highest usage). Click to keep showing this one" : "Show this limit in the menu bar"}
        >
          {limit.auto ? <span className="usage-pin-auto">Auto</span> : null}
          <span className="usage-radio" aria-hidden="true" />
        </button>
      </div>
      <div className="usage-bar">
        <div className="usage-bar-fill" style={{ width: `${shown}%`, background: barColor(limit.used) }} />
      </div>
    </div>
  );
}

/** UsageSpend: a card's More, its cost for today, yesterday and 30 days with the daily token trend. */
function Spend({ days: list, color }: { days: Day[]; color: string }) {
  const total = list.reduce((sum, day) => ({ tokens: sum.tokens + day.tokens, cost: sum.cost + day.cost }), { tokens: 0, cost: 0 });
  const max = Math.max(...list.map((day) => day.tokens), 1);
  const row = (label: string, w: { tokens: number; cost: number }) => (
    <div className="usage-detail-row">
      <span className="usage-detail-label">{label}</span>
      <span className="usage-detail-val" title={fmtCost(w.cost)}>
        <b>{fmtCost(w.cost)}</b> · {fmtTokens(w.tokens)} tokens
      </span>
    </div>
  );
  return (
    <div
      className="usage-detail"
      title="Standard short-context API-equivalent estimates from local token counts. Long-context and service-tier adjustments are not included."
    >
      <details className="usage-more-details">
        <summary>More</summary>
        <p className="usage-estimate-note" role="note">
          <Info size={12} aria-hidden="true" />
          <span>API estimate (short context), not billed spend.</span>
        </p>
        <div className="usage-detail-row">
          <span className="usage-detail-label">Token trend</span>
          <div
            className="usage-trend"
            role="img"
            aria-label="Daily token usage, last 30 days. Bar height represents tokens, not cost; pricing availability does not affect the bars."
          >
            {list.map((day) => (
              <span
                key={day.day}
                className="usage-trend-bar"
                style={{ height: `${day.tokens > 0 ? Math.max(2, Math.round((day.tokens / max) * 100)) : 0}%`, background: color }}
                title={`${day.day} · ${fmtTokens(day.tokens)} tokens · ${fmtCost(day.cost)}`}
              />
            ))}
          </div>
        </div>
        <div className="usage-detail-rows">
          {row("Today", list[list.length - 1])}
          {row("Yesterday", list[list.length - 2])}
          {row("Last 30 days", total)}
        </div>
      </details>
    </div>
  );
}

/** The Agent usage dropdown: Dropdown width 320, aligned like the app's. */
function AccountsPanel() {
  const [mode, setMode] = useState<UsageModeName>("left");
  return (
    <div className="menu menu-panel" style={{ width: 320, right: PANEL.edge, left: "auto", top: PANEL.top }}>
      <div className="menu-body usage-menu">
        <div className="usage-head menu-head">
          <span className="menu-head-title">Agent usage</span>
          <div className="usage-tools">
            <div className="usage-seg" role="group" title="Show remaining or used">
              <button type="button" className={mode === "left" ? "on" : ""} onClick={() => setMode("left")}>
                Left
              </button>
              <button type="button" className={mode === "used" ? "on" : ""} onClick={() => setMode("used")}>
                Used
              </button>
            </div>
            <button type="button" className="usage-refresh" title="Refresh">
              <RefreshCw size={13} />
            </button>
          </div>
        </div>
        {ACCOUNTS.map((account) => (
          <div key={`${account.agent}-${account.email}`} className="usage-card">
            <div className="usage-card-head" title={[account.name, account.plan, account.email].join(" · ")}>
              <span className="usage-brand" style={{ color: account.color }}>
                <AgentMark agent={account.agent} size={15} />
              </span>
              <span className="usage-name">{account.name}</span>
              <span className="usage-plan">{account.plan}</span>
              <span className="usage-email">{account.email}</span>
            </div>
            {account.limits.map((limit) => (
              <Bar key={limit.label} limit={limit} account={account.email} mode={mode} />
            ))}
            <Spend days={account.days} color={account.color} />
          </div>
        ))}
        <div className="usage-footer">
          <span>Show percentage</span>
          <button type="button" className="switch switch-sm" role="switch" aria-checked="false" title="Show percentage" aria-label="Show percentage">
            <span className="switch-knob" />
          </button>
        </div>
      </div>
    </div>
  );
}

